//! Copies the notification catalogue generated by Nix into `OUT_DIR`.
//!
//! The catalogue lives in `assets/notifications.nix` and is generated by
//! `nix/scripts/gen-notifications.py`. This build script does NOT generate it —
//! it only locates the finished file. Generating here would be reimplementing
//! Nix logic (invariant 5) and would leave the source of truth.
//!
//! The same shape as `ronoctua-tokens`'s build script, down to the reason the
//! destination is deleted first.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_NOTIFICATIONS_RS");

    let generated = env::var("RONOCTUA_NOTIFICATIONS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_NOTIFICATIONS_RS nao esta definida.\n\
             \n\
             O catalogo de notificacoes e gerado pelo Nix a partir de\n\
             assets/notifications.nix. Entre no ambiente com `direnv allow`\n\
             (ou `nix develop`), que define a variavel, ou construa pelo flake\n\
             com `nix build`.\n\
             \n\
             Gerar o catalogo aqui seria reimplementar logica Nix (invariante 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("notifications.rs");
    // DELETE FIRST. The file comes from the store, and `fs::copy` inherits the
    // read-only mode along with the content: on the second generation the
    // destination already exists without write permission and the copy fails
    // with "Permission denied", inside a build.rs. It is the trap the tokens'
    // build script already carries.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("nao consegui copiar {generated} -> {destination:?}: {e}"));
}
